{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early signs of pessimism (e.g., sentiment < 0.00).",
    "Increase forecast sensitivity to recent price spikes — if last 3-5 days show upward momentum, apply a lagged correction to avoid overshoot.",
    "Apply mean reversion bias when sentiment is neutral (0.00) and historical price volatility is high — reduce forecast drift toward extremes.",
    "When sentiment is positive (e.g., > 0.33) and forecast is below true outcome, increase forecast by 5-10% to capture sentiment-driven momentum.",
    "For long-term horizons (>10 days), reduce forecast volatility by 15-20% to account for lagged market adjustments.",
    "If true outcome consistently exceeds forecast by >10% over 3 consecutive days, apply a downward bias correction to prevent overconfidence in short-term spikes."
  ]
}
